!function(){"use strict";var n=[{id:"jp-contract-001",title:"合同违约金调整的司法审查标准",cause:"合同纠纷",causeColor:"blue",source:"最高人民法院",author:"最高法民二庭",date:"2023-05-15",summary:"约定违约金过分高于造成的损失的, 当事人可以请求人民法院或仲裁机构予以适当减少; 约定的违约金低于造成的损失的, 当事人可以请求人民法院或仲裁机构予以增加。",fullText:'【裁判要旨】\n\n合同纠纷案件中, 违约金的调整应当以实际损失为基础, 兼顾合同的履行情况、当事人的过错程度以及预期利益等综合因素, 根据公平原则和诚实信用原则予以衡量。\n\n【裁判规则】\n\n一、违约金是否过高的判断标准\n《民法典》第五百八十五条规定的"过分高于造成的损失"司法实践中, 一般以约定的违约金是否超过造成损失的 30% 为判断标准。\n\n二、举证责任分配\n主张违约金过高的一方, 应当对违约金过分高于损失承担举证责任; 主张增加违约金的, 同样需要举证证明实际损失高于约定违约金。\n\n三、调整幅度\n违约金的调整应遵循"补偿性为主, 惩罚性为辅"的原则, 一般不超过实际损失的 130%。',applicableScenarios:["买卖合同逾期付款纠纷","借款合同利息/违约金计算","租赁合同提前解约违约金","服务合同违约赔偿"],relatedLaws:["《民法典》第五百八十五条","《民法典》第五百八十四条","《全国法院贯彻实施民法典工作会议纪要》(法〔2021〕94 号)"],citedCases:["最高人民法院 (2019) 民终 1342 号民事判决书","最高人民法院公报案例 2020 年第 6 期"],tags:["违约金","合同纠纷","民法典"]},{id:"jp-contract-002",title:"合同效力性强制性规定的识别与适用",cause:"合同纠纷",causeColor:"blue",source:"最高人民法院",author:"最高法第六巡回法庭",date:"2022-11-20",summary:"判断某项规定是否属于效力性强制性规定, 应当考察其立法目的、立法精神和条文表述, 而非仅从字面理解。",fullText:"【裁判要旨】\n\n人民法院在判断某条款是否属于效力性强制性规定时, 应当综合考察: (1) 该规定的立法目的和立法精神; (2) 该规定的具体条文表述; (3) 违反该规定的法律后果; (4) 合同类型和交易安全。\n\n【裁判规则】\n\n一、识别标准\n根据《民法典》第一百五十三条和最高人民法院《关于适用民法典合同编通则若干问题的解释》第十六条, 强制性规定分为管理性规范和效力性规范, 前者不影响合同效力, 后者导致合同无效。\n\n二、典型情形\n1. 违反金融监管规定 (如未经许可的场外配资合同无效)\n2. 违反税收征管规定 (阴阳合同以阴合同为准)\n3. 违反市场准入规定 (如房地产开发的资质要求)\n4. 违反公序良俗 (如包二奶协议无效)",applicableScenarios:["合同效力争议","股权代持协议效力","场外配资合同效力","违反强制性规定行为认定"],relatedLaws:["《民法典》第一百五十三条","《民法典》第一百五十五条","《关于适用民法典合同编通则若干问题的解释》"],citedCases:["最高人民法院 (2018) 民终 942 号","最高人民法院 (2020) 民申 5678 号"],tags:["合同效力","效力性强制规定","合同无效"]},{id:"jp-contract-003",title:"格式条款的司法认定与不利解释规则",cause:"合同纠纷",causeColor:"blue",source:"最高人民法院",author:"最高法民二庭",date:"2023-09-08",summary:"格式条款是当事人为了重复使用而预先拟定, 并在订立合同时未与对方协商的条款。对格式条款的理解发生争议的, 应当按照通常理解予以解释。",fullText:'【裁判要旨】\n\n格式条款的认定应当从"预先拟定"和"未与对方协商"两个特征进行判断。提供格式条款的一方未尽到合理提示及说明义务, 致使对方没有注意或者理解与其有重大利害关系的条款, 对方可以主张该条款不成为合同内容。\n\n【裁判规则】\n\n一、提示说明义务的履行标准\n《民法典》第四百九十六条规定的"合理方式"应达到"足以引起对方注意"的客观标准, 包括但不限于: 加粗、变色、下划线、特别提示框等。\n\n二、不利解释规则的适用\n《民法典》第四百九十八条规定, 格式条款有两种以上解释的, 应当作出不利于提供格式条款一方的解释。\n\n三、格式条款无效的情形\n《民法典》第四百九十七条列举了格式条款无效的三种情形, 司法实践中应严格把握。',applicableScenarios:["网络购物合同纠纷","保险合同纠纷","银行/金融借款合同纠纷","物业管理服务合同纠纷"],relatedLaws:["《民法典》第四百九十六条","《民法典》第四百九十七条","《民法典》第四百九十八条"],citedCases:["最高人民法院公报案例 2019 年第 8 期","最高人民法院 (2021) 民申 2345 号"],tags:["格式条款","不利解释","合同解释"]},{id:"jp-marriage-001",title:"离婚案件中夫妻共同财产认定标准",cause:"婚姻家事",causeColor:"pink",source:"最高人民法院",author:"最高法民一庭",date:"2023-03-22",summary:"夫妻在婚姻关系存续期间所得的财产, 原则上归夫妻共同所有。但有约定或法律特别规定的除外。",fullText:'【裁判要旨】\n\n夫妻共同财产的认定以"婚姻关系存续期间"为时间节点, 取得方式 (劳动/继承/受赠) 和财产形态 (动产/不动产/知识产权) 均不影响共同财产属性。\n\n【裁判规则】\n\n一、属共同财产的情形\n《民法典》第一千零六十二条列举的 5 项 + 兜底条款, 包括: 工资/奖金/劳务报酬, 生产/经营/投资的收益, 知识产权的收益, 继承或受赠的财产 (除非明确只归一方), 其他应当归共同所有的财产。\n\n二、属个人财产的情形\n《民法典》第一千零六十三条: 一方婚前的财产, 一方因受伤残疾得到的补助, 遗嘱或赠与合同中确定只归一方的财产, 一方专用的生活用品, 其他应当归一方的财产。\n\n三、特殊处理\n1. 婚后公积金: 双方共同缴存部分及收益为共同财产\n2. 婚后还贷的婚前房产: 共同还贷部分及增值部分为共同财产\n3. 父母出资购房: 需结合意思表示 (借款/赠与) 认定',applicableScenarios:["离婚财产分割","夫妻财产约定效力认定","婚前财产婚后收益归属","父母出资购房性质认定"],relatedLaws:["《民法典》第一千零六十二条","《民法典》第一千零六十三条","《最高人民法院关于适用民法典婚姻家庭编的解释 (一)》"],citedCases:["最高人民法院 (2020) 民申 4567 号","最高人民法院公报案例 2021 年第 4 期"],tags:["夫妻共同财产","离婚","财产分割"]},{id:"jp-marriage-002",title:"离婚损害赔偿的法定情形与举证标准",cause:"婚姻家事",causeColor:"pink",source:"最高人民法院",author:"最高法民一庭",date:"2022-12-15",summary:"《民法典》第一千零九十一条规定的离婚损害赔偿, 必须由无过错方举证证明对方存在法定过错情形。",fullText:'【裁判要旨】\n\n离婚损害赔偿请求权的主体是无过错方。无过错方主张损害赔偿, 应当对对方存在重婚、与他人同居、实施家庭暴力、虐待遗弃家庭成员、有其他重大过错五种法定情形之一承担举证责任。\n\n【裁判规则】\n\n一、法定过错的认定\n1. 重婚: 包含法律上的重婚和事实上的重婚\n2. 与他人同居: 持续稳定的共同生活, 不包括偶尔的婚外性行为\n3. 家庭暴力: 包括身体和精神两个层面, 可申请人身安全保护令作为证据\n4. 虐待遗弃: 持续性/经常性家庭暴力或对家庭成员不尽扶养义务\n5. 其他重大过错: 如赌博/吸毒等恶习屡教不改\n\n二、举证责任分配\n适用"谁主张, 谁举证"原则, 但部分情形 (如家庭暴力) 适用举证责任缓和, 可根据已知事实推定。\n\n三、赔偿范围\n包括物质损害赔偿和精神损害赔偿, 后者一般不超过 5 万元。',applicableScenarios:["离婚损害赔偿诉讼","家庭暴力认定","出轨行为取证","虐待遗弃情形认定"],relatedLaws:["《民法典》第一千零九十一条","《反家庭暴力法》","《最高人民法院关于适用民法典婚姻家庭编的解释 (一)》"],citedCases:["最高人民法院 (2019) 民申 3456 号","最高人民法院公报案例 2018 年第 12 期"],tags:["离婚损害赔偿","家庭暴力","过错方"]},{id:"jp-tort-001",title:"网络服务提供者侵权责任的认定与免责",cause:"侵权责任",causeColor:"orange",source:"最高人民法院",author:"最高法民一庭",date:"2024-01-10",summary:"网络用户利用网络服务实施侵权行为的, 权利人有权通知网络服务提供者采取删除、屏蔽、断开链接等必要措施。",fullText:'【裁判要旨】\n\n网络服务提供者根据《民法典》第一千一百九十五至一千一百九十七条承担侵权责任, 适用"避风港原则"和"红旗原则"。\n\n【裁判规则】\n\n一、网络服务提供者的类型化责任\n1. 内容服务提供者: 直接侵权责任\n2. 接入/缓存服务提供者: 通知 - 删除规则 (避风港)\n3. 信息存储服务提供者: 通知 - 删除 + 应知/明知 (红旗)\n4. 搜索/链接服务提供者: 通知 - 删除规则\n\n二、避风港原则的适用条件\n1. 接到权利人通知后及时删除\n2. 不知道也没有合理理由知道侵权\n3. 未直接参与侵权\n4. 未从侵权行为中获利\n\n三、红旗原则的适用\n"侵权事实明显, 像红旗一样飘扬"时, 即使未接到通知, 网络服务提供者亦构成应知/明知, 不得主张免责。',applicableScenarios:["网络名誉权侵权","网络著作权侵权","电商平台经营者责任","短视频/直播平台责任"],relatedLaws:["《民法典》第一千一百九十四条","《民法典》第一千一百九十五条","《民法典》第一千一百九十六条","《信息网络传播权保护条例》"],citedCases:["最高人民法院 (2018) 民申 2233 号","最高人民法院公报案例 2022 年第 3 期"],tags:["网络侵权","避风港原则","红旗原则"]},{id:"jp-tort-002",title:"高空抛物致害责任的法律适用",cause:"侵权责任",causeColor:"orange",source:"最高人民法院",author:"最高法民一庭",date:"2023-08-05",summary:"从建筑物中抛掷物品或者从建筑物上坠落的物品造成他人损害的, 由侵权人依法承担侵权责任; 经调查难以确定具体侵权人的, 除非能够证明自己不是侵权人的外, 由可能加害的建筑物使用人给予补偿。",fullText:'【裁判要旨】\n\n高空抛物致害责任是《民法典》第一千一百五十四条新增的特殊侵权责任, 适用"难以确定具体侵权人时的建筑物使用人补偿责任", 并允许使用人通过举证免责。\n\n【裁判规则】\n\n一、责任主体\n1. 具体侵权人 (能确定时): 承担侵权责任\n2. 建筑物使用人 (难以确定时): 补偿责任, 非真正连带责任\n3. 物业管理人: 安全保障义务, 过错责任\n4. 建筑物所有人: 一般无责, 例外情形除外\n\n二、使用人免责事由\n《民法典》第一千一百五十四条第二款规定的免责事由: "能够证明自己不是侵权人的", 包括: 不在建筑物内、当时不在场、有相反证据等。\n\n三、补偿责任的内部追偿\n建筑物使用人之间不构成真正连带责任, 但可在查明具体侵权人后, 自行向其追偿。',applicableScenarios:["高空抛物砸伤","高空坠物损害","建筑物使用人认定","物业服务企业责任"],relatedLaws:["《民法典》第一千一百五十四条","《民法典》第一千一百九十八条","《关于依法妥善审理高空抛物坠物案件的意见》(法发〔2019〕25 号)"],citedCases:["最高人民法院公报案例 2020 年第 10 期","最高人民法院 (2021) 民申 6789 号"],tags:["高空抛物","建筑物使用人","补偿责任"]},{id:"jp-criminal-001",title:"合同诈骗罪与民事合同欺诈的界分",cause:"刑事",causeColor:"red",source:"最高人民法院",author:"最高法刑二庭",date:"2023-04-18",summary:"区分合同诈骗罪与民事合同欺诈的关键在于行为人是否具有非法占有目的, 以及是否实施虚构事实或者隐瞒真相的欺骗行为。",fullText:"【裁判要旨】\n\n合同诈骗罪 (《刑法》第二百二十四条) 与民事合同欺诈行为在客观上均表现为虚构事实或隐瞒真相, 但二者具有本质区别, 应准确界分, 防止以刑事手段干预经济纠纷。\n\n【裁判规则】\n\n一、构成合同诈骗罪的核心要件\n1. 主体为合同当事人\n2. 在签订/履行合同过程中实施欺骗\n3. 骗取对方财物数额较大\n4. 主观上具有非法占有目的\n\n二、非法占有目的的认定\n综合判断: 主体是否真实存在、是否有履约能力、是否提供虚假担保、是否按约使用资金、是否逃匿、是否承认债务等。\n\n三、典型情形\n1. 主体虚假 (冒用他人名义或虚构单位)\n2. 担保虚假 (伪造票据/产权证明)\n3. 履约能力虚假 (无资金/无技术/无货源)\n4. 逃匿或挥霍\n5. 拒不返还或拒不交代去向\n\n四、与民事欺诈的区别\n民事欺诈一般不具有非法占有目的, 仅在合同履行过程中夸大/虚假陈述, 不影响合同可履行性。",applicableScenarios:["合同诈骗刑事辩护","合同欺诈控告","非法占有目的认定","刑民交叉案件"],relatedLaws:["《刑法》第二百二十四条","《全国法院审理金融犯罪案件工作座谈会纪要》","《最高人民法院关于审理诈骗案件具体应用法律的若干问题的解释》"],citedCases:["最高人民法院公报案例 2019 年第 11 期","最高人民法院 (2018) 刑申 1234 号"],tags:["合同诈骗","非法占有","刑民交叉"]},{id:"jp-criminal-002",title:"正当防卫的认定与防卫过当的边界",cause:"刑事",causeColor:"red",source:"最高人民法院",author:"最高法刑一庭",date:"2024-02-25",summary:"正当防卫明显超过必要限度造成重大损害的, 应当负刑事责任, 但应当减轻或者免除处罚。",fullText:"【裁判要旨】\n\n《刑法》第二十条规定的正当防卫, 应当具备起因条件 (不法侵害现实存在) 、时间条件 (正在进行) 、主观条件 (防卫意识) 、对象条件 (针对侵害人) 、限度条件 (没有明显超过必要限度) 。\n\n【裁判规则】\n\n一、防卫过当的认定\n1. 明显超过必要限度: 防卫强度显著超过必要程度\n2. 造成重大损害: 重伤、死亡或重大财产损失\n3. 防卫过当应当负刑事责任, 但应当减轻或免除处罚\n\n二、特殊防卫 (《刑法》第二十条第三款)\n对正在进行行凶、杀人、抢劫、强奸、绑架以及其他严重危及人身安全的暴力犯罪, 采取防卫行为, 造成不法侵害人伤亡的, 不属于防卫过当, 不负刑事责任。\n\n三、特殊场景\n1. 防卫时精神紧张致超过必要限度: 应当从宽\n2. 侵害人无责任能力: 不影响正当防卫成立\n3. 互殴与正当防卫的区分: 关键看谁先动手",applicableScenarios:["正当防卫认定","防卫过当刑事辩护","特殊防卫适用","互殴与防卫界分"],relatedLaws:["《刑法》第二十条","《最高人民法院、最高人民检察院、公安部关于依法适用正当防卫制度的指导意见》"],citedCases:["最高人民法院公报案例 2020 年第 6 期 (于欢案)","最高人民法院 (2021) 刑申 4567 号"],tags:["正当防卫","防卫过当","特殊防卫"]},{id:"jp-admin-001",title:"行政处罚合理性原则与显失公正的判断",cause:"行政",causeColor:"purple",source:"最高人民法院",author:"最高法行政庭",date:"2023-06-12",summary:'行政处罚显失公正的, 人民法院可以判决变更。判断"显失公正"应当综合考量违法情节、主观过错、社会危害性等因素。',fullText:'【裁判要旨】\n\n《行政诉讼法》第七十七条规定的"显失公正"是行政处罚合理性审查的核心标准, 司法实践中应严格适用, 避免以合理性审查替代合法性审查。\n\n【裁判规则】\n\n一、显失公正的判断标准\n1. 违反过罚相当原则: 处罚结果与违法行为不相当\n2. 违反比例原则: 存在更轻的可替代处罚\n3. 违反平等原则: 同类违法行为处罚畸重\n4. 违反信赖利益保护: 处罚结果有失公平\n\n二、常见情形\n1. 轻微违法处以最高档次罚款\n2. 主动消除危害后果仍按上限处罚\n3. 同案不同罚 (缺乏合理理由)\n4. 处罚结果明显违反比例原则\n\n三、变更原则\n"显失公正"应通过变更判决处理, 不得撤销行政处罚; 变更应遵循"就低不就高"原则, 在法定幅度内选择最低档次。',applicableScenarios:["行政处罚合理性审查","罚款畸重认定","行政诉讼变更判决","比例原则适用"],relatedLaws:["《行政诉讼法》第七十七条","《行政处罚法》第四条","《行政处罚法》第三十二条"],citedCases:["最高人民法院公报案例 2019 年第 9 期","最高人民法院 (2020) 行申 3456 号"],tags:["行政处罚","显失公正","比例原则"]},{id:"jp-ip-001",title:"商标近似与混淆可能性的判断标准",cause:"知识产权",causeColor:"indigo",source:"最高人民法院",author:"最高法知识产权法庭",date:"2023-11-28",summary:"认定商标近似, 应当从商标的音、形、义和整体表现等方面, 以相关公众的一般注意力为标准, 采取整体观察与显著部分比较相结合的方法。",fullText:'【裁判要旨】\n\n商标近似的判断以"相关公众的一般注意力"为标准, 需综合考虑商标的音、形、义、整体视觉效果、显著性、使用情况、实际混淆等因素。\n\n【裁判规则】\n\n一、判断原则\n1. 整体观察与显著部分比较相结合\n2. 以相关公众的一般注意力为标准, 不以专家或特定群体标准\n3. 隔离观察原则 (分别观察而非对比观察)\n4. 考虑商标的显著性和知名度\n\n二、判定近似的考量因素\n1. 商标的整体结构/外观/呼叫/含义\n2. 显著识别部分\n3. 是否属于驰名商标/著名商标\n4. 商品/服务的关联程度\n5. 实际混淆的证据\n6. 被告的主观意图\n\n三、典型情形\n1. 字形近似 + 读音相同 + 含义相近\n2. 图形部分相同 + 整体布局相似\n3. 文字 + 图形组合商标显著部分相同',applicableScenarios:["商标侵权认定","商标近似判断","混淆可能性认定","商标行政诉讼"],relatedLaws:["《商标法》第五十七条","《最高人民法院关于审理商标民事纠纷案件适用法律若干问题的解释》","《商标审查审理指南》(2021 年修订)"],citedCases:["最高人民法院 (2019) 知民终 567 号","最高人民法院公报案例 2021 年第 9 期"],tags:["商标近似","混淆可能性","商标侵权"]},{id:"jp-execution-001",title:"执行异议之诉的审理与裁判规则",cause:"执行",causeColor:"gray",source:"最高人民法院",author:"最高法执行局",date:"2023-10-15",summary:"执行异议之诉应当审查执行标的的权属、案外人权利的真实性、合法性以及能否排除强制执行。",fullText:'【裁判要旨】\n\n《民事诉讼法》第二百三十八条规定的执行异议之诉, 是案外人对执行标的主张实体权利的诉讼, 应当围绕"能否排除强制执行"这一核心进行审理。\n\n【裁判规则】\n\n一、审查范围\n1. 案外人对执行标的是否享有实体权利\n2. 该权利的真实性、合法性和有效性\n3. 该权利能否排除强制执行 (优先性)\n4. 执行所依据的生效法律文书是否正确\n\n二、常见排除执行的情形\n1. 案外人对执行标的享有所有权 (已支付全款 + 实际占有 + 未过户非自身原因)\n2. 案外人对执行标的享有建设工程价款优先受偿权\n3. 案外人对执行标的上享有租赁权 (在先租赁)\n4. 案外人对被执行人享有其他优先债权 (如税款)\n\n三、不能排除执行的情形\n1. 单纯金钱债权 (无优先性)\n2. 未经登记的物权期待权 (一般情形)\n3. 自身原因未办理过户登记的不动产受让人',applicableScenarios:["执行异议之诉","案外人权利保护","排除强制执行","执行标的权属争议"],relatedLaws:["《民事诉讼法》第二百三十八条","《最高人民法院关于人民法院办理执行异议和复议案件若干问题的规定》","《全国法院民商事审判工作会议纪要》(九民纪要)"],citedCases:["最高人民法院 (2020) 民申 4567 号","最高人民法院公报案例 2021 年第 6 期"],tags:["执行异议","排除执行","案外人权利"]}];globalThis.judicialPoints=n,globalThis.getAllJudicialPoints=function(){return n},globalThis.getJudicialPointById=function(a){return n.find(function(n){return n.id===a})},globalThis.getJudicialCauses=function(){var a=new Set;return n.forEach(function(n){a.add(n.cause)}),Array.from(a)},globalThis.getJudicialTags=function(){var a=new Set;return n.forEach(function(n){(n.tags||[]).forEach(function(n){a.add(n)})}),Array.from(a)}}();